/* 座標APIの替え玉が返す固定表。記事名 → [経度, 緯度]。
   ここに無い記事は「座標なし」＝地図に立たない、として扱う。

   固定ストリーム（stream.mjs）の記事名に合わせてある。
   日本の記事3件・フランス1件にしてあるので、「いちばん書き換わっている場所＝日本」になる。 */

export const COORDS = {
  秋田県: [140.1025, 39.7186],
  東京駅: [139.7669, 35.6811],
  自動販売機: null, // 実在するが座標は持たない記事の代表
  図書館: [139.6917, 35.6895], // 日本（東京）
  駅: [2.3522, 48.8566], // フランス（パリ）に置いて、国が複数になるようにしている
  記事1: [13.405, 52.52],
  記事2: [-0.1276, 51.5072],
};

// 値が null のものは表から外す（「聞いたが座標が無かった」を再現するため）
for (const [key, value] of Object.entries(COORDS)) if (!value) delete COORDS[key];
